var DB=load();
function load(){try{var s=localStorage.getItem(KEY);if(s){s=s.replace(/컨테이너/g,'프로세스');/* 용어 변경(컨테이너→프로세스) 전에 저장된 데이터 보정 */var o=JSON.parse(s);if(o&&o.length)return o}}catch(e){}return JSON.parse(JSON.stringify(SEED))}
function save(){try{localStorage.setItem(KEY,JSON.stringify(DB))}catch(e){}}
function nextId(){var n=DB.reduce(function(m,c){return Math.max(m,parseInt(c.id.slice(2),10)||0)},0)+1;return 'CT'+String(n).padStart(4,'0')}
function fmtDt(s){if(!s)return '';var d=s.replace(/-/g,'.');return d.length===16?d+':00':d}
function now(){var d=new Date(),p=function(n){return String(n).padStart(2,'0')};return d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate())+' '+p(d.getHours())+':'+p(d.getMinutes())+':'+p(d.getSeconds())}
function sbadge(s){var c={'운영':'b-run','검증완료':'b-info','초안':'b-draft','사용중지':'b-stop'}[s]||'b-draft';return '<span class="badge '+c+'">'+esc(s)+'</span>'}
function ccount(c){return c.stages.reduce(function(n,s){return n+s.corners.length},0)}
function scount(c){return c.stages.filter(function(s){return s.corners.length}).length}

$('crumb-list').addEventListener('click',function(e){e.preventDefault();if(editable())confirmDlg('히스토리로 이동하시겠습니까?','저장하지 않은 변경 사항은 사라집니다.',backToList);else backToList()});

/* ---------- 상세 / 등록 / 수정 ---------- */
/* cs = 미리보기·편집 대상 템플릿, openI = 펼친 템플릿(-1 = 모두 접힘, B안처럼 한 번에 하나만 펼침) */
var cur=null, mode='view', cs=0, openI=0, sel=null, orig=null;
function deep(o){return JSON.parse(JSON.stringify(o))}
function openDetail(id,m){
  mode=m; cs=0; openI=0; sel=null; vfState=null;
  // 새로 만들 때는 빈 안내 대신 '새로 만들기'를 누른 것처럼 빈 템플릿 1개를 펼친 상태로 시작한다
  if(m==='new'){cur={id:null,use:'N',cat:'',name:'',ptype:[],ch:['통합app'],status:'초안',appr:'임시 저장',desc:'',stages:[{name:'',screen:'',custom:true,corners:[]}],mod:'',by:''};}
  else{cur=deep(DB.filter(function(c){return c.id===id})[0]);}
  orig=deep(cur);
  $('view-detail').hidden=false;$('d-scroll').scrollTop=0;
  renderDetail();
}
function editable(){return mode!=='view'}
/* 정책서 3.1·4.3 상품유형별 초기 구성 프리셋 — 생성 시 시작 구성만 채우고 저장 후에는 독립 프로세스로 관리 */
var PRESETS=SEED.map(function(s,i){return {src:i,ptype:s.ptype[0],cat:s.cat}}).filter(function(p){return p.cat==='상품 유형 프로세스'}).map(function(p){var s=SEED[p.src];return {ptype:p.ptype,src:p.src,note:s.name.replace('상품 유형_','')+' · '+s.stages.filter(function(x){return x.corners.length}).length+'단계'}});
function openPreset(){
  $('dlg-root').innerHTML='<div class="dim" id="dlg"><div class="dlg"><h3>초기 구성 프리셋 불러오기<button type="button" class="x" data-x>✕</button></h3><p>상품유형별 기본 단계·코너 구성을 불러옵니다. 불러온 뒤 자유롭게 편집할 수 있으며, 저장한 프로세스는 프리셋과 독립적으로 관리되어 이후 프리셋이 바뀌어도 영향을 받지 않습니다.</p><div class="preset">'+PRESETS.map(function(p,i){var s=SEED[p.src];return '<div class="pick" data-pi="'+i+'"><div><b>'+esc(p.ptype)+'</b><small>'+esc(p.note)+' · 코너 '+ccount(s)+'개</small></div></div>'}).join('')+'</div><div class="acts"><button type="button" class="btn outline" data-x>닫기</button></div></div></div>';
  var dlg=$('dlg');dlg.addEventListener('click',function(e){
    if(e.target.closest('[data-x]')||e.target===dlg){$('dlg-root').innerHTML='';return}
    var p=e.target.closest('[data-pi]');if(!p)return;var pr=PRESETS[+p.getAttribute('data-pi')],s=deep(SEED[pr.src]);
    var apply=function(){cur.ptype=[pr.ptype];cur.stages=s.stages;cs=0;openI=0;sel=null;$('dlg-root').innerHTML='';renderDetail();toast(pr.ptype+' 프리셋을 불러왔습니다.')};
    if(ccount(cur)){$('dlg-root').innerHTML='';confirmDlg('현재 구성을 프리셋으로 바꾸시겠습니까?','배치한 코너와 설정이 프리셋 구성으로 대체됩니다.',apply)}else apply();
  });
}
function renderDetail(){
  if(mode==='view'){vfState=null;closeSheet()}setTimeout(renderVf,0);
  var ro=!editable();
  $('d-scroll').classList.toggle('ro-mode',ro);
  $('d-crumb').textContent=mode==='new'?'주문 프로세스 등록':mode==='edit'?'주문 프로세스 수정':'주문 프로세스 상세';
  $('d-title').textContent=mode==='new'?'주문 프로세스 등록':mode==='edit'?'주문 프로세스 수정':'주문 프로세스 상세';

  $('d-acts').innerHTML='';
  var al=$('d-alert');
  if(cur.stale){al.hidden=false;al.innerHTML='<b>최신 코너 업데이트 필요</b>&nbsp;포함된 코너에 새 버전이 등록되었습니다. 운영 중인 프로세스는 자동으로 바뀌지 않으니, 수정 화면에서 미리보기와 선택지를 확인한 뒤 저장해 주세요.'}else al.hidden=true;

  // 기본 정보
  $('b-id').value=cur.id||'';$('b-id').placeholder=cur.id?'':'등록 시 자동채번';
  $('b-name').value=cur.name;$('b-name').disabled=ro;
  $('b-desc').value=cur.desc;$('b-desc').disabled=ro;
  $('b-cat').value=cur.cat||'';$('b-cat').disabled=ro;
  $('b-ptype').value=cur.ptype[0]||'';$('b-ptype').disabled=ro;
  var u=cur.use||(cur.status==='사용중지'?'N':'Y');$('b-use-y').checked=u==='Y';$('b-use-n').checked=u==='N';$('b-use-y').disabled=ro;$('b-use-n').disabled=ro;
  syncClr();ddAll();
  ['e-name','e-ptype','e-cat'].forEach(function(i){$(i).hidden=true});$('b-name').classList.remove('err');

  renderCfg(false);
  // 하단 바
  var f=$('d-foot');
  if(ro){f.innerHTML='<div class="l"><button class="btn outline" type="button" data-a="list">히스토리</button><span class="dock-sum" id="d-sum"></span></div><div class="r"><button class="btn filled" type="button" data-a="edit">수정</button></div>';}
  else{f.innerHTML='<div class="l"><span class="dock-sum" id="d-sum"></span><button type="button" class="vfchip" data-a="sheet" aria-expanded="false" aria-controls="vf-sheet">구성 검증 <span class="stc" id="d-vf"></span><svg class="dock-chev" viewBox="0 0 24 24" aria-hidden="true"><path d="m6 15 6-6 6 6"/></svg></button></div><div class="r"><button class="btn outline" type="button" data-a="cancel">취소</button>'+'<button class="btn grey" type="button" data-a="verify">전체 구성 검증</button>'+'<button class="btn filled" type="button" data-a="save">저장</button></div>';}
}
(function(){PTYPES.forEach(function(p){var o=document.createElement('option');o.textContent=p;$('b-ptype').appendChild(o)})})();
$('b-ptype').addEventListener('change',function(){cur.ptype=this.value?[this.value]:[];if(this.value)$('e-ptype').hidden=true});
$('b-cat').addEventListener('change',function(){cur.cat=this.value;if(this.value)$('e-cat').hidden=true});
$('b-use').addEventListener('change',function(e){cur.use=e.target.value});
document.addEventListener('mousedown',function(e){if(e.target.closest&&e.target.closest('.clr-x'))e.preventDefault()},true);
function syncClr(){[].forEach.call(document.querySelectorAll('.clr-x'),function(b){var i=$(b.getAttribute('data-clr'));b.hidden=!i.value||i.disabled})}
document.addEventListener('input',function(e){if(e.target.closest&&e.target.closest('.clr'))syncClr()});
document.addEventListener('click',function(e){var b=e.target.closest('.clr-x');if(!b)return;var i=$(b.getAttribute('data-clr'));i.value='';i.dispatchEvent(new Event('input',{bubbles:true}));i.focus()});
$('b-name').addEventListener('input',function(){cur.name=this.value});
$('b-desc').addEventListener('input',function(){cur.desc=this.value});


/* 전체 구성 검증 — 저장 없이 필수값·탭명·코너·노출 조건·선택지·배치 제약을 한 번에 점검 */
/* 구성 검증 — 검증 전 / 검증 완료 / 재검증 필요 / 검증 실패(오류·경고) */
var vfState=null; /* null=검증 전 | {items:[{lv:'err'|'warn',cat,t,si,c}],snap,at} */
function vfSnap(){return JSON.stringify({n:cur.name,cat:cur.cat,pt:cur.ptype,use:cur.use,st:cur.stages.map(function(s){return {sc:s.screen,c:s.corners.map(function(c){return {id:c.id,om:c.omode,r:c.rules}})}})})}
function vfCollect(){
  var L=[],E=function(cat,t,si,c){L.push({lv:'err',cat:cat,t:t,si:si,c:c})},W=function(cat,t,si,c){L.push({lv:'warn',cat:cat,t:t,si:si,c:c})};
  if(!cur.name.trim())E('설정 항목','기본 정보의 프로세스명이 입력되지 않았습니다.');
  if(!cur.cat)E('설정 항목','기본 정보의 전시 상품유형이 선택되지 않았습니다.');
  if(!cur.ptype.length)E('설정 항목','기본 정보의 연결 대상 상품 유형이 선택되지 않았습니다.');
  if(!cur.stages.length)E('설정 항목','구성된 단계가 없습니다. 새로 만들거나 기존 프로세스를 복제해주세요.');
  cur.stages.forEach(function(s,i){var tn=(s.screen||'').trim()||(i+1)+'번째 단계';
    if(!(s.screen||'').trim())E('설정 항목',(i+1)+'번째 단계의 템플릿명이 입력되지 않았습니다.',i);
    if(!s.corners.length)E('설정 항목','\''+tn+'\' 단계에 배치된 코너가 없습니다.',i);
    s.corners.forEach(function(c){var m=CMAP[c.id];if(!m)return;
      if(m.status==='사용중지'||m.status==='폐기')E('코너 상태','\''+m.n+'\' 코너가 코너 관리에서 '+m.status+' 상태로 변경되어 더 이상 사용할 수 없습니다.',i,c);
      else if(!ADDABLE[m.status])W('코너 상태','\''+m.n+'\' 코너가 코너 관리에서 '+m.status+' 상태입니다. 운영 반영 전 검증 완료가 필요합니다.',i,c);
    });
  });
  var f=flatC();
  f.forEach(function(x,p){var c=x.c,n=cnm(c.id),sv=svOf(c);if(c.omode!=='cond'||!sv)return;
    (c.rules||[]).forEach(function(r,ri){var g='\''+n+'\' 코너의 조건 그룹 '+(ri+1);
      if(!r.target){E('조건',g+'에 후행 코너가 선택되지 않았습니다.',x.si,c);return}
      var t=byIdC(r.target),tn='\''+cnm(r.target)+'\'';
      if(!t)E('조건 충돌',g+'의 후행 코너 '+tn+'이(가) 프로세스에 없어 적용할 수 없습니다.',x.si,c);
      else if(t.p<=p)E('조건 충돌',g+'의 후행 코너 '+tn+'이(가) 이 코너보다 앞에 있어 적용할 수 없습니다. 순서를 바꿔주세요.',x.si,c);
      if(!r.opts.some(Boolean))E('조건',g+'에 노출할 선택지가 선택되지 않았습니다.',x.si,c);
      else if(r.opts.length&&r.opts.every(Boolean))W('조건',g+'에 '+tn+'의 모든 선택지가 선택되어 기본 노출과 동일합니다.',x.si,c);
      if(!r.vals.length)E('조건',g+'에 조건이 될 선택값이 없습니다.',x.si,c);
      else if(r.vals.length===sv.length)W('조건','\''+n+'\' 코너의 조건 그룹 '+(ri+1)+'에 모든 선택값이 선택되어 항상 노출과 동일합니다.',x.si,c);
      for(var j=0;j<ri;j++){var a=c.rules[j];if(a.target!==r.target||!a.vals.length||!r.vals.length)continue;
        if(r.vals.every(function(v){return a.vals.indexOf(v)>=0})){E('조건 충돌',g+'은(는) 같은 후행 코너를 대상으로 한 조건 그룹 '+(j+1)+'에 가려져 어떤 경우에도 적용되지 않습니다.',x.si,c);break}}
    });
  });
  return L;
}
/* 구성 검증은 하단 고정 영역(dock) 안에서 바 위로 펼친다 (하단 바 '구성 검증' 칩 / '전체 구성 검증' 버튼) */
function setDock(open){var c=document.querySelector('#d-foot [data-a="sheet"]');$('dock').classList.toggle('open',open);$('vf-dim').hidden=!open;if(c)c.setAttribute('aria-expanded',String(open))}
function openSheet(){if(mode==='view')return;var s=$('vf-sheet');renderVf();s.hidden=false;setDock(true);void s.offsetWidth;s.classList.add('on');$('vf-close').focus()}
function closeSheet(){var s=$('vf-sheet');if(!s||s.hidden)return;s.classList.remove('on');setDock(false);setTimeout(function(){if(!s.classList.contains('on'))s.hidden=true},180)}
$('vf-sheet').addEventListener('click',function(e){if(e.target.closest('#vf-close'))closeSheet();else if(e.target.closest('#vf-rerun'))verifyAll()});
$('vf-dim').addEventListener('click',closeSheet);
function renderVf(){
  setTimeout(renderSt,0);
  var el=$('vf');if(!el)return;if(mode==='view')return;
  $('vf-at').textContent=vfState&&vfState.at?vfState.at+' 검증':'';
  if(!vfState){el.innerHTML='<div class="vf-box"><b>아직 검증하지 않았습니다.</b><span>\'전체 구성 검증\'을 클릭하면 코너 간 조건 충돌 / 코너 상태 변경 영향 / 설정 항목을 확인합니다.</span></div>';return}
  if(vfSnap()!==vfState.snap){el.innerHTML='<div class="vf-box warn"><b>구성이 변경되었습니다.</b><span>이전 검증 결과는 더 이상 유효하지 않습니다. \'전체 구성 검증\'을 다시 실행해주세요.</span></div>';return}
  var L=vfState.items,ne=L.filter(function(x){return x.lv==='err'}).length,nw=L.length-ne;
  if(!L.length){el.innerHTML='<div class="vf-box ok"><b>검증 완료</b><span>조건 충돌 / 코너 상태 변경 영향 / 설정 항목을 확인했습니다.</span></div>';return}
  el.innerHTML='<div class="vf-box '+(ne?'ng':'warn')+'"><b>'+(ne?'검증 실패':'검증 완료 (경고)')+' - 오류 '+ne+'건 / 경고 '+nw+'건</b><ul class="vf-rows">'+L.map(function(x,i){return '<li><em class="'+x.lv+'">'+(x.lv==='err'?'오류':'경고')+'</em><span><b>['+esc(x.cat)+']</b> '+esc(x.t)+'</span>'+(x.si!=null?'<button type="button" class="lnk" data-vgo="'+i+'">바로가기</button>':'')+'</li>'}).join('')+'</ul></div>';
}
function verifyAll(){var p=function(n){return String(n).padStart(2,'0')},d=new Date();vfState={items:vfCollect(),snap:vfSnap(),at:p(d.getHours())+':'+p(d.getMinutes())};openSheet()}
/* 바로가기: 시트를 닫고 해당 템플릿을 펼친 뒤 코너가 있으면 선택한다 */
document.addEventListener('click',function(e){var b=e.target.closest&&e.target.closest('[data-vgo]');if(!b||!vfState)return;var x=vfState.items[+b.getAttribute('data-vgo')];if(x.si==null||!cur.stages[x.si])return;closeSheet();cs=openI=x.si;sel=x.c||null;renderCfg(false);goAcc(x.si)});
document.addEventListener('input',function(e){if(mode!=='view'&&vfState)renderVf()});
document.addEventListener('change',function(e){if(mode!=='view'&&vfState)renderVf()});
$('d-foot').addEventListener('click',function(e){
  var b=e.target.closest('[data-a]');if(!b)return;var a=b.getAttribute('data-a');
  if(a==='list')return backToList();
  if(a==='edit'){mode='edit';orig=deep(cur);renderDetail();return}
  if(a==='copy'){startCopy();return}
  if(a==='cancel'){confirmDlg('변경 사항을 취소하시겠습니까?','수정한 내용은 저장되지 않습니다.',function(){if(mode==='new')backToList();else{cur=deep(orig);mode='view';renderDetail()}});return}
  if(a==='save')return doSave();
  if(a==='verify')return verifyAll();
  if(a==='sheet')return $('vf-sheet').classList.contains('on')?closeSheet():openSheet();
  if(a==='stop'){confirmDlg('이 프로세스를 사용중지하시겠습니까?','운영 중인 채널에 즉시 반영되며, 연결된 주문 흐름에서 노출되지 않습니다.',function(){cur.status='사용중지';commit('사용중지 처리되었습니다.')});return}
  if(a==='del'){confirmDlg('초안을 삭제하시겠습니까?','삭제한 초안은 복구할 수 없습니다.',function(){DB=DB.filter(function(c){return c.id!==cur.id});save();backToList();toast('초안을 삭제했습니다.')});return}
});
function doSave(){
  var ok=true;
  if(!cur.name.trim()){ok=false;$('e-name').hidden=false;$('b-name').classList.add('err')}
  if(!cur.cat){ok=false;$('e-cat').hidden=false}
  if(!cur.ptype.length){ok=false;$('e-ptype').hidden=false}
  var oi=optIssues();if(oi.length){ok=false;sel=oi[0].c;cs=openI=oi[0].si;renderCfg(false);toast(oi[0].t,true)}
  var ve=vfCollect().filter(function(x){return x.lv==='err'});if(ok&&ve.length){ok=false;vfState={items:vfCollect(),snap:vfSnap(),at:''};openSheet();toast('구성 검증에서 오류 '+ve.length+'건이 발견되어 저장할 수 없습니다. 구성 검증 결과를 확인하세요.',true);return}
  if(!ok){$('d-scroll').scrollTop=0;return}
  var et=cur.stages.findIndex(function(s){return !(s.screen||'').trim()});if(et>=0){cs=openI=et;sel=null;renderCfg(false);goAcc(et);$('scr').focus();toast('템플릿명을 입력하세요.',true);return}
  if(!ccount(cur)){toast('코너를 1개 이상 배치하세요.',true);return}
  var go=function(){commit(mode==='new'?'프로세스를 등록했습니다.':'저장되었습니다.')};
  go();
}
function commit(msg){
  cur.mod=now();cur.by='김미연';cur.byId='P123456';cur.name=cur.name.trim();
  if(!cur.id){cur.id=nextId();DB.unshift(deep(cur))}else{var i=DB.findIndex(function(c){return c.id===cur.id});DB[i]=deep(cur)}
  save();mode='view';orig=deep(cur);renderDetail();toast(msg);
}
function startCopy(){var c=deep(cur);c.id=null;c.name=cur.name+' (복제)';c.status='초안';c.appr='임시 저장';c.prod=0;c.stale=false;cur=c;mode='new';orig=deep(cur);cs=0;openI=0;sel=null;renderDetail();$('d-scroll').scrollTop=0;toast('구성을 복제했습니다. 프로세스명을 확인해 주세요.')}
