/* 드래그: 코너 행(같은 템플릿 안 순서) / 템플릿 머리줄 ⠿ (템플릿 순서) */
var dragI=null,dragS=null;
function clrOver(){[].forEach.call($('acc').querySelectorAll('.over'),function(x){x.classList.remove('over')})}
