  var g=e.target.closest&&e.target.closest('.agrip');if(g){dragS=+g.closest('.acc').getAttribute('data-s');g.closest('.acc').classList.add('drag');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain','');return}
