/* ---------- FO 화면 예시 (코너 관리 등록 정의 → 화면) ---------- */
function splitTxt(t,n){return String(t||'').replace(/\([A-Z]{3,4}-M\d\d\)/g,'').split(/[,·]\s*|\s*\/\s*/).map(function(x){return x.trim()}).filter(function(x){return x&&x.length<24}).slice(0,n||3)}

/* ---------- FO 화면 템플릿 (실제 주문서 화면) — 코너 ID별, 노출할 선택지(opts) 반영 ---------- */
function fx(opts,list){return opts&&opts.length?list.filter(function(x){return opts.indexOf(x[0])>=0}):list}
function fxCards(items,selFirst,mk){return '<div class="fx-list">'+items.map(function(x,i){return mk(x,i===0&&selFirst)}).join('')+'</div>'}
function fxH(t,s,more){return '<div class="fx-h"><div><div class="fx-t">'+t+'</div>'+(s?'<div class="fx-s">'+s+'</div>':'')+'</div>'+(more?'<span class="fx-more">'+more+'</span>':'')+'</div>'}
function fxNd(x,on,right){return '<div class="fx-c'+(on?' on':'')+'"><div class="b"><span class="n">'+x[0]+'</span>'+(x[1]?'<span class="d">'+x[1]+'</span>':'')+'</div>'+(right||'')+'</div>'}
