function foHtml(m,opts){
  if(FOX[m.id])return FOX[m.id](opts);
  var d=m.def||{},ft=m.ft,items=d.items&&d.items.length?d.items:null,h=fxH(esc(d.title||m.n),d.sub?esc(d.sub):'');
  if(ft==='선택'){items=items||(m.opts||['선택지 1','선택지 2']).map(function(x){return {n:x}});if(opts&&opts.length)items=items.filter(function(x){return opts.indexOf(x.n)>=0});
    h+='<div class="fx-list">'+items.map(function(x,i){return fxNd([esc(x.n),esc(x.d||'')],i===0,x.v?'<span class="r">'+esc(x.v)+'</span>':'')}).join('')+'</div>';}
  else if(ft==='입력'){h+=(items||splitTxt(m.cin,3).map(function(x){return {n:x}})).map(function(x){return '<div class="fx-f"><label>'+esc(x.n)+'</label><div class="in'+(x.v?' v':'')+'">'+esc(x.v||x.d||'입력해 주세요')+'</div></div>'}).join('')}
  else if(ft==='인증'){h+='<div class="fx-list">'+(items?items.map(function(x){return x.n}):['PASS 인증','휴대폰 본인확인','신용카드 인증']).map(function(x){return '<div class="fx-c" style="justify-content:center"><span class="n">'+esc(x)+'</span></div>'}).join('')+'</div>'}
  else if(ft==='외부연결'){h+='<div class="fx-c"><div class="b"><span class="n b6">'+esc(m.n)+'</span><span class="d">외부 화면으로 이동합니다</span></div><span class="ar">›</span></div>'}
  else if(ft==='검증'||ft==='상태'){h+='<div class="fx-st"><i></i><div>'+esc(splitTxt(m.cout,2).join(' · ')||'처리 결과를 확인했어요')+'</div></div>'}
  else{h+='<div class="fx-info">'+(items||splitTxt(m.cout,3).map(function(x){return {n:x}})).map(function(x){return '<div><span>'+esc(x.n)+'</span><b>'+esc(x.v||'—')+'</b></div>'}).join('')+'</div>'}
  if(d.cta)h+='<span class="fx-btn">'+esc(d.cta)+'</span>';
  if(!m.def)h+='<div class="fx-gen">* 코너 관리 화면 구성 미등록 — 기능유형 기본 예시</div>';
  return h;
}

